<div class="top"><div><h2 style="margin:0">Bank statement matching</h2><span class="muted"><a href="/staff/reports">&larr; Reports</a> &middot; Upload a CSV statement; matching payments are suggested. The file is read once and not stored.</span></div></div>
<div class="card mb" style="max-width:720px"><form method="post" action="/staff/bank/upload" enctype="multipart/form-data"><?= csrf_field() ?><label for="bs">Statement (.csv with a header row: Date, Narration/Description, Debit/Withdrawal, Credit/Deposit or Amount)</label><input id="bs" type="file" name="statement" accept=".csv,text/csv" required><button class="btn">Read statement</button></form></div>
<?php if ($rows): ?><div class="card"><div style="display:flex;justify-content:space-between;align-items:center"><h3 style="margin:0"><?= count($rows) ?> transactions</h3><form method="post" action="/staff/bank/clear" class="inline"><?= csrf_field() ?><button class="btn link">Clear</button></form></div>
<div class="tw"><table><tr><th>Date</th><th>Narration</th><th class="right">Money in</th><th class="right">Money out</th><th>Suggestion</th></tr>
<?php foreach ($rows as $r): $m = $r['match']; ?><tr><td><?= e(fmt_date($r['date'])) ?></td><td style="white-space:normal;max-width:320px"><?= e($r['text']) ?></td><td class="right"><?= $r['credit'] > 0 ? e(money($r['credit'])) : '' ?></td><td class="right"><?= $r['debit'] > 0 ? e(money($r['debit'])) : '' ?></td>
<td style="white-space:normal"><?php if ($m && $m['type'] === 'invoice'): $i = $m['row']; ?><?= $m['sure'] ? badge('Match', 'p-ok') : badge('Check', 'p-warn') ?> <a href="/staff/invoices/<?= (int) $i['id'] ?>"><?= e($i['number']) ?></a> <?= e($i['bill_name']) ?> (balance <?= e(money($i['bal'])) ?>)
<form method="post" action="/staff/invoices/<?= (int) $i['id'] ?>" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="pay"><input type="hidden" name="back" value="bank"><input type="hidden" name="amount" value="<?= e(number_format($r['credit'], 2, '.', '')) ?>"><input type="hidden" name="paid_at" value="<?= e($r['date']) ?>"><input type="hidden" name="method" value="Bank transfer"><input type="hidden" name="ref" value="<?= e(mb_substr($r['text'], 0, 60)) ?>"><button class="btn sm" data-confirm="Record <?= e(money($r['credit'])) ?> received on <?= e($i['number']) ?>?">Record payment</button></form>
<?php elseif ($m && $m['type'] === 'bill'): $b = $m['row']; ?><?= $m['sure'] ? badge('Match', 'p-ok') : badge('Check', 'p-warn') ?> <a href="/staff/bills/<?= (int) $b['id'] ?>"><?= e($b['bill_no']) ?></a> <?= e($b['sname']) ?> (balance <?= e(money($b['bal'])) ?>)
<form method="post" action="/staff/bills/<?= (int) $b['id'] ?>" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="pay"><input type="hidden" name="back" value="bank"><input type="hidden" name="amount" value="<?= e(number_format($r['debit'], 2, '.', '')) ?>"><input type="hidden" name="paid_on" value="<?= e($r['date']) ?>"><input type="hidden" name="method" value="Bank transfer"><input type="hidden" name="ref" value="<?= e(mb_substr($r['text'], 0, 60)) ?>"><button class="btn sm" data-confirm="Record <?= e(money($r['debit'])) ?> paid on bill <?= e($b['bill_no']) ?>?">Record payment</button></form>
<?php else: ?><span class="muted">no open invoice or bill matches</span><?php endif; ?></td></tr><?php endforeach; ?></table></div></div><?php endif; ?>
